{
  "outcome": "deny",
  "rationale": "We deny this claim because the loss occurred while the vehicle was being driven off a maintained public or private road on a dirt trail. This event triggers the off-road use exclusion under section BASIC-4.7. Consequently, collision coverage does not apply to this incident.",
  "citations": [
    {
      "clause_id": "BASIC-4.7",
      "quote": "We do not cover loss that occurs while the covered vehicle is being driven off a maintained public or private road, including on trails, fields, beaches, dunes or other unimproved terrain."
    }
  ]
}
